from review_helpers import *
for lang in ('da','en'):
 d=rd('onboarding-'+lang+'.json')
 # Align character names to this edition, including the correct feminine surname.
 names={'Sonya Marmeladov':'Sonia Marmeladova','Sonya':'Sonia','Sonja':'Sonia','Dunya':'Dounia','Dunja':'Dounia','Razumikhin':'Razumihin','Svidrigailov':'Svidrigaïlov','Svidrigajlov':'Svidrigaïlov','Porfiry Petrovich':'Porfiry Petrovitch','Porfirij':'Porfiry','Romanovitj':'Romanovitch','Avdotja':'Avdotya','Rodja':'Rodya','Luzjin':'Luzhin'}
 def norm(x):
  if isinstance(x,str):
   for a,b in names.items():x=x.replace(a,b)
   return x
  if isinstance(x,list):return [norm(a) for a in x]
  if isinstance(x,dict):return {k:norm(v) for k,v in x.items()}
  return x
 d=norm(d)
 if lang=='da':
  d['title']='Forbrydelse og straf'
  d['openingText']=rd('modern-da.json')['chapters'][0]['paragraphs'][0]+' '+rd('modern-da.json')['chapters'][0]['paragraphs'][1].split(' Hver gang')[0]
  d['about']='Forbrydelse og straf følger Rodion Romanovitch Raskolnikov, en fattig tidligere student i Sankt Petersborg. Han myrder en gammel pantlåner og hendes søster, som uventet kommer ind. Han har udtænkt en teori om, at usædvanlige mennesker kan have ret til at overskride loven for at gennemføre en stor idé. Men mordet giver ham hverken den frihed eller den sikkerhed på sig selv, han havde forestillet sig. Feber, frygt, stolthed og behovet for andre mennesker trækker ham i forskellige retninger.\n\nOmkring ham står søsteren Dounia, moderen Pulcheria Alexandrovna, vennen Razumihin og Sonia, som har prostitueret sig for at hjælpe sin familie. Efterforskeren Porfiry prøver hans forklaringer og driver ham mod en tilståelse. Godsejeren Svidrigaïlov giver spørgsmålet om frihed uden moralske grænser en anden og urovækkende form.\n\nRomanen fra 1866 forener en forbrydelsesfortælling med en undersøgelse af samvittighed, fattigdom, tro og ansvar. En tilståelse er ikke det samme som anger, og en straf er ikke i sig selv en forvandling. Netop afstanden mellem de ting gør slutningen værd at diskutere.'
  d['angleCards'][0]['angleObjective']='Jeg vil følge, hvordan Raskolnikov forsvarer og udfordrer sin teori, også efter at mordet har fået katastrofale følger.'
  d['angleCards'][1]['text']='Raskolnikov sveder, hallucinerer, kollapser og raser. Jeg vil lægge mærke til, hvordan romanen forbinder hans tanker med kroppens reaktioner, og hvor svært det er at skelne skyldfølelse fra frygt, sygdom og såret stolthed.'
  d['angleCards'][3]['text']='Tilståelsen og epilogens begyndende forvandling er to forskellige øjeblikke. Jeg vil undersøge, hvad der får Raskolnikov til at overgive sig, og om slutningen gør hans forandring overbevisende.'
  d['angleCards'][3]['angleObjective']='Jeg vil skelne mellem tilståelse, straf og anger og undersøge, hvad der faktisk forandrer Raskolnikov.'
  d['cast'][0]['description']='En fattig tidligere jurastuderende på treogtyve år, der bor i et meget lille værelse i Sankt Petersborg. Han er stolt og skarp, men også gavmild, grusom, sårbar og fuld af modsætninger. Hans teori om usædvanlige menneskers rettigheder bliver sat på prøve af hans egne handlinger. Fortællingen følger ham tæt, men bevæger sig også ind i andre menneskers liv og synsvinkler.'
  d['cast'][1]['description']='En ung kvinde, der prostituerer sig for at hjælpe sin far, stedmor og de sultende børn. Hun er from og medfølende, men hendes liv rummer også frygt, ydmygelse og fortvivlelse. Hun lytter til Raskolnikovs tilståelse, opfordrer ham til at tage ansvar og følger ham til Sibirien.'
  d['cast'][2]['description']='En efterforsker, der kombinerer en jovial fremtræden med skarpe spørgsmål og psykologisk pres. Han lader Raskolnikov tale, udfordrer hans teori og konfronterer ham til sidst direkte med sin mistanke. Deres samtaler forbinder opklaringen af mordet med romanens moralske strid.'
  d['cast'][4]['description']='En velhavende godsejer, som forfølger Dounia og forsøger at få magt over hende. Rygter om tidligere overgreb omgiver ham. Hans kynisme og begær gør ham til et urovækkende modstykke til Raskolnikov, men hans handlinger omfatter også økonomisk hjælp til Sonia og børnene. Romanen gør ham vanskelig at reducere til en enkelt forklaring.'
  d['cast'][5]['description']='Raskolnikovs fattige, energiske og loyale ven. Han passer ham under sygdommen, hjælper hans familie og forelsker sig i Dounia. Hans praktiske omsorg og vilje til at arbejde giver en anden vej gennem fattigdommen end Raskolnikovs teori.'
  d['whyItMatters']=[{'title':'En tæt skildring af et splittet sind','body':'Romanen følger Raskolnikovs skift mellem selvretfærdiggørelse, panik, stolthed og længsel efter kontakt. Læseren kender gerningsmanden fra begyndelsen; spændingen ligger også i, hvad han vil forstå om sig selv. Drømme, feber og samtaler gør tankelivet til handling. Det er en stærk psykologisk roman, men hverken den første af sin slags eller en fortælling, der udelukkende foregår i hans hoved.'},{'title':'Hvem har ret til at overskride loven?','body':'Raskolnikov bruger store lovgivere, opdagere og erobrere som eksempler i sin teori. Han vil afgøre, om han selv hører til dem, der må gå ud over de almindelige regler. Romanen undersøger spændingen mellem denne tanke og de konkrete mennesker, den gør til midler. Hans lidelse efter mordet kan ikke uden videre sidestilles med anger: selv i fængslet forsvarer han længe sin idé.'},{'title':'Sonia, tro og ansvar','body':'Sonia læser beretningen om Lazarus for Raskolnikov og beder ham erkende sin handling offentligt. Hendes medfølelse ophæver ikke kravet om ansvar. Epilogen forbinder hendes kærlighed og tro med muligheden for et nyt liv, men kalder hans forvandling begyndelsen på en anden historie. Læseren må selv vurdere, hvor overbevisende det løfte er.'}]
 else:
  d['about']='Crime and Punishment follows Rodion Romanovitch Raskolnikov, a poor former student in St. Petersburg. He murders an old pawnbroker and her sister, who enters unexpectedly. He has developed a theory that extraordinary people may be entitled to break the law in pursuit of a great idea. The murder gives him neither the freedom nor the certainty about himself that he imagined. Fever, fear, pride and his need for other people pull him in different directions.\n\nAround him are his sister Dounia, his mother Pulcheria Alexandrovna, his friend Razumihin and Sonia, who has turned to prostitution to support her family. The investigator Porfiry tests his explanations and presses him toward confession. The landowner Svidrigaïlov gives the question of freedom without moral limits another disturbing form.\n\nPublished in 1866, the novel combines a crime story with an inquiry into conscience, poverty, faith and responsibility. Confession is not the same as repentance, and punishment does not by itself produce transformation. The distance between these things makes its ending worth debating.'
  d['angleCards'][0]['angleObjective']='I want to follow how Raskolnikov defends and questions his theory, even after the murder has brought disastrous consequences.'
  d['angleCards'][1]['text']='Raskolnikov sweats, hallucinates, collapses and rages. I want to notice how the novel connects his thoughts to bodily reactions, and how difficult it is to distinguish guilt from fear, illness and wounded pride.'
  d['angleCards'][3]['text']='The confession and the beginning of transformation in the epilogue are separate moments. I want to examine what makes Raskolnikov surrender and whether the ending makes his change convincing.'
  d['angleCards'][3]['angleObjective']='I want to distinguish confession, punishment and repentance, and ask what actually changes Raskolnikov.'
  d['cast'][0]['description']='A poor former law student of twenty-three, living in a tiny room in St. Petersburg. Proud and intelligent, he is also generous, cruel, vulnerable and contradictory. His theory of extraordinary people’s rights is tested by his own actions. The narrative follows him closely but also enters other people’s lives and perspectives.'
  d['cast'][1]['description']='A young woman who turns to prostitution to support her father, stepmother and the hungry children. Devout and compassionate, she also experiences fear, humiliation and despair. She listens to Raskolnikov’s confession, urges him to accept responsibility and follows him to Siberia.'
  d['cast'][2]['description']='An investigator who combines a jovial manner with sharp questions and psychological pressure. He lets Raskolnikov talk, challenges his theory and eventually confronts him directly with his suspicions. Their conversations connect the investigation with the novel’s moral conflict.'
  d['cast'][4]['description']='A wealthy landowner who pursues Dounia and tries to gain power over her. Rumours of earlier abuse surround him. His cynicism and appetite make him a disturbing counterpart to Raskolnikov, but his actions also include financial help for Sonia and the children. The novel makes him difficult to reduce to a single explanation.'
  d['cast'][5]['description']='Raskolnikov’s poor, energetic and loyal friend. He nurses him during his illness, helps his family and falls in love with Dounia. His practical care and willingness to work offer another way through poverty than Raskolnikov’s theory.'
  d['whyItMatters']=[{'title':'A Close Portrait of a Divided Mind','body':'The novel follows Raskolnikov’s shifts between self-justification, panic, pride and longing for human contact. Readers know the murderer from the start; the suspense also concerns what he will understand about himself. Dreams, fever and conversations turn thought into action. This is a powerful psychological novel, but neither the first of its kind nor a narrative confined entirely to his consciousness.'},{'title':'Who May Break the Law?','body':'Raskolnikov draws on lawgivers, discoverers and conquerors in explaining his theory. He wants to find out whether he belongs among those entitled to exceed ordinary rules. The novel tests that idea against the actual people it turns into instruments. His suffering after the murder cannot simply be equated with repentance: even in prison, he continues to defend his idea.'},{'title':'Sonia, Faith and Responsibility','body':'Sonia reads Raskolnikov the story of Lazarus and asks him to acknowledge his act publicly. Her compassion does not remove the demand for responsibility. The epilogue links her love and faith with the possibility of a new life, but calls his transformation the beginning of another story. Readers must judge how convincing that promise is.'}]
 wr('onboarding-'+lang+'.json',d)
